/* mpe_tables.h - the motion tables of the minipupperesp reference firmware.
 *
 * minipupperesp (C:\esp6\projects\minipupperesp) is the build whose movement is
 * verified on this robot. Its generated tables are copied here unchanged:
 *
 *   longjump_table.h  Long Jump (Lite 3 style) + Far Jump - sim/jump_opt.py
 *   trajopt_jump.h    spin jumps + the Character moves (play bow, chase tail,
 *                     dig, give paw, running man, push-ups ...) - generated by
 *                     minipupper_trajopt/step5_export.py
 *
 * To update one, regenerate it there and copy the file over this one. The
 * players (robot/moves_mpe.inc) are line-for-line ports of main.c's lj_play()
 * and tj_play().
 */
#pragma once

#include <stdint.h>

/* ---- Long Jump / Far Jump tables (lj_play) ----------------------------
 * A track is a list of segments; each moves the foot from where the previous
 * one left it to (x, z), starting at t0 and taking dur ms, linearly (the
 * pushes) or eased. x = fore/aft foot position (mm, + forward), z = hip
 * height above the foot (mm). Both tracks start from the stand. */
typedef struct { int16_t t0, dur; float x, z; uint8_t ease; } lj_seg_t;
typedef struct {
    const lj_seg_t *front; int nfront;
    const lj_seg_t *rear;  int nrear;
    int fast0, fast1;      /* table ms: fast0..fast1 always runs at real speed */
    int end;               /* table ms: the table is done                      */
    int rise;              /* ms (at 100%) for the stand-up afterwards         */
    float reach;           /* longest leg allowed, mm (103; 105.5 = straight)  */
} lj_jump_t;

#include "robot/longjump_table.h"
#include "robot/trajopt_jump.h"
